45	        BigDecimal seguro = Dinheiro.percentual(compra.subtotal(), regiao.taxaSeguro());
46	        BigDecimal total = compra.subtotal().subtract(desconto).add(frete).add(seguro);
47	
48	        FormaPagamento forma = formasPagamento.buscar(pedido.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
49	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
50	        if (!forma.parcelasPermitidas(parcelas)) {
51	            throw new RecusaException("PARCELAMENTO_INVALIDO");
52	        }
53	        if (!forma.atende(total)) {
54	            throw new RecusaException("FORMA_PAGAMENTO_INDISPONIVEL");
55	        }
56	        Cobranca cobranca = forma.cobrar(total, parcelas);
57	
58	        return new ResumoResponse(
59	                compra.subtotal(),
60	                desconto,
61	                frete,
62	                entrega.prazoDias(),
63	                seguro,
64	                cobranca.totalFinal().subtract(total),
65	                cobranca.totalFinal(),
66	                parcelas,
67	                cobranca.valorParcela(),
68	                nivel.credito(compra),
69	                nivel.brinde(compra));
70	    }
71	
72	    private BigDecimal desconto(String codigoCupom, Compra compra, BigDecimal frete) {
73	        if (codigoCupom == null) {
74	            return Dinheiro.ZERO;
75	        }
76	        Cupom cupom = cupons.buscar(codigoCupom, "CUPOM_INVALIDO");
77	        if (!cupom.aplicavel(compra)) {
78	            throw new RecusaException("CUPOM_NAO_APLICAVEL");
79	        }
80	        return cupom.desconto(compra, frete);
81	    }
82	
83	    private static Regiao regiao(String codigo) {
84	        try {
85	            return Regiao.valueOf(codigo);
86	        } catch (IllegalArgumentException | NullPointerException e) {
87	            throw new RecusaException("REGIAO_INVALIDA");
88	        }
89	    }
90	
91	    private static List<Item> itens(PedidoRequest pedido) {
92	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
93	            throw new RecusaException("PEDIDO_INVALIDO");
94	        }
95	        return pedido.itens().stream().map(ResumoService::item).toList();
96	    }
97	
98	    private static Item item(PedidoRequest.ItemRequest item) {
99	        if (item == null
100	                || item.precoUnitario() == null || item.precoUnitario().signum() <= 0
101	                || item.quantidade() == null || item.quantidade() <= 0
102	                || item.pesoKg() == null || item.pesoKg().signum() <= 0) {
103	            throw new RecusaException("PEDIDO_INVALIDO");
104	        }
105	        return new Item(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
106	    }
107	}
