1	package loja.checkout.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	
6	import org.springframework.stereotype.Component;
7	
8	import loja.checkout.comum.Dinheiro;
9	
10	@Component
11	class Cartao implements FormaPagamento {
12	    private static final int MAX_SEM_JUROS = 3;
13	    private static final int MAX_PARCELAS = 12;
14	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean parcelasPermitidas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
24	    }
25	
26	    @Override
27	    public Cobranca cobrar(BigDecimal total, int parcelas) {
28	        BigDecimal n = BigDecimal.valueOf(parcelas);
29	        if (parcelas <= MAX_SEM_JUROS) {
30	            return new Cobranca(total, Dinheiro.arredondar(total.divide(n, MathContext.DECIMAL128)));
31	        }
32	        BigDecimal fator = BigDecimal.ONE.add(TAXA).pow(parcelas, MathContext.DECIMAL128);
33	        BigDecimal parcela = total.multiply(TAXA).multiply(fator)
34	                .divide(fator.subtract(BigDecimal.ONE), MathContext.DECIMAL128);
35	        BigDecimal valorParcela = Dinheiro.arredondar(parcela);
36	        return new Cobranca(Dinheiro.arredondar(valorParcela.multiply(n)), valorParcela);
37	    }
38	}
